import{_ as t,o as a,a as o,a2 as i}from"./chunks/framework.DCcmcJcL.js";const s="/images/blade-tracer.png",m=JSON.parse('{"title":"Blade Tracer","description":"","frontmatter":{},"headers":[],"relativePath":"tools/blade-tracer.md","filePath":"tools/blade-tracer.md","lastUpdated":1789464754000}'),r={name:"tools/blade-tracer.md"};function n(d,e,h,l,c,p){return a(),o("div",null,e[0]||(e[0]=[i(`<h1 id="blade-tracer" tabindex="-1">Blade Tracer <a class="header-anchor" href="#blade-tracer" aria-label="Permalink to &quot;Blade Tracer&quot;">​</a></h1><p>The Blade Tracer writes the path of every rendered Blade file into the page&#39;s HTML and, on the storefront, shows that path when you hover over an element. Use it during development to find the view or component behind any part of a page, for example before overriding it in a theme.</p><h2 id="where-it-lives" tabindex="-1">Where It Lives <a class="header-anchor" href="#where-it-lives" aria-label="Permalink to &quot;Where It Lives&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Piece</th><th>Where</th><th>What it does</th></tr></thead><tbody><tr><td>Switch</td><td><code>tracer</code> in <code>config/view.php</code></td><td><code>false</code> by default</td></tr><tr><td>Compiler</td><td><code>Webkul\\Core\\View\\Compilers\\BladeCompiler</code>, bound as <code>blade.compiler</code> in <code>packages/Webkul/Core/src/Providers/CoreServiceProvider.php</code></td><td>While the tracer is on, <code>appendFilePath()</code> adds a <code>data-blade-path</code> attribute holding the file&#39;s path, relative to the project root, to the first HTML element of each compiled view, or wraps the view in a <code>&lt;span&gt;</code> that carries it</td></tr><tr><td>Overlay</td><td><code>core::blade.tracer.style</code>, in <code>packages/Webkul/Core/src/Resources/views/blade/tracer/style.blade.php</code></td><td>Draws the outlines and the hover label, and adds the copy shortcut. It is added through the <code>bagisto.shop.layout.body.after</code> and <code>bagisto.admin.layout.head</code> render events</td></tr></tbody></table><h2 id="enabling-the-tracer" tabindex="-1">Enabling the Tracer <a class="header-anchor" href="#enabling-the-tracer" aria-label="Permalink to &quot;Enabling the Tracer&quot;">​</a></h2><p>The value isn&#39;t read from the environment, so change it in the file:</p><p><strong>File:</strong> <code>config/view.php</code></p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;?</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">php</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &#39;tracer&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // ...</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">];</span></span></code></pre></div><p>The path is written into each view when Blade compiles it, so clear the views compiled before the change:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> view:clear</span></span></code></pre></div><p>If your configuration is cached, run <code>php artisan optimize:clear</code> instead, so the new value is read as well.</p><h2 id="using-the-tracer" tabindex="-1">Using the Tracer <a class="header-anchor" href="#using-the-tracer" aria-label="Permalink to &quot;Using the Tracer&quot;">​</a></h2><p>On a storefront page:</p><ol><li>Every traced element has a thin red outline, drawn thicker while you hover over it.</li><li>Hover over an element. A label at the bottom left of the window shows the Blade file that rendered it, such as <code>/packages/Webkul/Shop/src/Resources/views/components/layouts/header/desktop/bottom.blade.php</code>.</li><li>Click the clipboard icon in the label, or press <strong>Ctrl + Shift + C</strong> (<strong>Cmd + Shift + C</strong> on macOS) while hovering, to copy the path.</li></ol><p><img src="`+s+'" alt="Blade Tracer Demo"></p><p>To override the file you found, place a copy at the same relative path in your theme; see <a href="./../theme-development/creating-store-theme.html#how-views-are-resolved">How Views Are Resolved</a>. A path under <code>views/components/</code> belongs to a Blade component, whose override path in the theme drops the <code>components</code> segment.</p><h2 id="disabling-the-tracer" tabindex="-1">Disabling the Tracer <a class="header-anchor" href="#disabling-the-tracer" aria-label="Permalink to &quot;Disabling the Tracer&quot;">​</a></h2><p>Set <code>&#39;tracer&#39; =&gt; false</code> and run <code>php artisan view:clear</code> again. Until the views are recompiled, they keep their attributes.</p><h2 id="things-to-watch" tabindex="-1">Things to Watch <a class="header-anchor" href="#things-to-watch" aria-label="Permalink to &quot;Things to Watch&quot;">​</a></h2><ul><li><strong>Development only.</strong> The attributes expose your directory layout to anyone who reads the page source. Never enable the tracer in production.</li><li><strong>Every compiled view is traced</strong>, including the emails and PDF documents rendered from Blade. Turn the tracer off before you test mail output.</li><li><strong>Most admin pages show no overlay.</strong> The overlay is attached to the <code>bagisto.admin.layout.head</code> event, which only the admin&#39;s anonymous layout for the sign-in pages fires; the main admin layout fires <code>bagisto.admin.layout.head.before</code> and <code>.after</code>. The <code>data-blade-path</code> attributes are still in the HTML, so inspect an element in your browser&#39;s developer tools to read them.</li><li><strong>Vue-rendered markup is traced on its root only.</strong> The attribute lands on a component&#39;s <code>&lt;v-…&gt;</code> element, and Vue passes it on to the root element the component renders from its <code>x-template</code>, so the elements inside show the component&#39;s own path; a component with several root elements shows the nearest traced ancestor instead. Search the <code>components</code> directories for the <code>v-</code> name to find its template.</li><li><strong>The copy shortcut is always taken on the storefront.</strong> The overlay&#39;s script is added to every storefront page, even while the tracer is off, and it claims <strong>Ctrl + Shift + C</strong> (<strong>Cmd + Shift + C</strong>), which is also the browser&#39;s inspect-element shortcut. Open the inspector from the context menu or with F12 instead.</li></ul><h2 id="related-pages" tabindex="-1">Related Pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related Pages&quot;">​</a></h2><ul><li><a href="./../theme-development/blade-components.html">Blade Components</a>: the components behind most <code>components/</code> paths.</li><li><a href="./../advanced/view-render-events.html">View Render Events</a>: add markup next to a view without overriding it.</li><li><a href="./../advanced/debugging.html">Debugging Tips</a>: the debug bar and the other debugging tools.</li></ul>',22)]))}const u=t(r,[["render",n]]);export{m as __pageData,u as default};
